"""Summary figure for the tracker study -> reports/figures/bl_trk_logic.png"""
import sys, os, warnings, json; sys.path.insert(0, '.'); warnings.filterwarnings('ignore')
import numpy as np, pandas as pd, matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt
from scipy.stats import poisson
from bl_common import OUT
FIG = os.path.join(os.path.dirname(OUT), 'reports', 'figures'); Pr = pd.read_csv(f'{OUT}/bl_react_pairs.csv'); C = pd.read_csv(f'{OUT}/bl_trk_counts.csv'); CV = pd.read_csv(f'{OUT}/bl_trk_sim_cv.csv'); CV2 = pd.read_csv(f'{OUT}/bl_trk_sim2_cv.csv'); AL = pd.read_csv(f'{OUT}/bl_trk_sim_all.csv'); SP = pd.read_csv(f'{OUT}/bl_trk_sim2_splits.csv'); CR = pd.read_csv(f'{OUT}/bl_trk_sim2_cross.csv')
fig, ax = plt.subplots(2, 2, figsize=(13.5, 9.5))
a = ax[0, 0]; r = (Pr[Pr.reactive].te.values % 60).astype(int); s = (Pr[Pr.sched].te.values % 60).astype(int); a.hist(r, bins=np.arange(0, 61, 5), weights=np.ones(len(r)) / len(r) * 100, alpha=.7, color='#d62728', label='reactive pairs'); a.hist(s, bins=np.arange(0, 61, 5), weights=np.ones(len(s)) / len(s) * 100, alpha=.5, color='#7f7f7f', label='scheduled (timer) pairs'); a.axhline(100 / 12, color='k', ls=':', label='uniform'); a.set_xlabel('second of the minute'); a.set_ylabel('% of pairs'); a.legend(fontsize=8); a.set_title('A. Reactive pairs are not tied to a fixed second of the minute')
a = ax[0, 1]; x = C.reactive_pairs.values; vc = pd.Series(x).value_counts().sort_index(); k = np.arange(2, 20); a.bar(vc.index, vc.values, color='#d62728', alpha=.8, label='cycles (observed)'); a.plot(k, 32 * poisson.pmf(k, x.mean()), 'ko-', ms=3, label='if arrivals were random (Poisson)'); a.set_xlabel('reactive pairs in the D-1 session'); a.set_ylabel('cycles'); a.legend(fontsize=8); a.set_title(f'B. {x.mean():.1f} ± {x.std(ddof=1):.1f} pairs per day: more regular than random')
a = ax[1, 0]; m = ['M0', 'M1', 'M2', 'M3', 'M4']; nm = ['range edge\nstateless', 'range edge\n+ refractory', 'reference\nmove', 'swing\n(zig-zag)', 'range edge\n+ swing']; f = [CV[(CV.family == k_) & (CV['info'] == 'bar')].F1_tol1.iloc[0] for k_ in m]; nl = [CV[(CV.family == k_) & (CV['info'] == 'bar')].null_F1_p99.iloc[0] for k_ in m]; xx = np.arange(5); a.bar(xx, f, color=['#7f7f7f', '#d62728', '#7f7f7f', '#7f7f7f', '#7f7f7f']); a.scatter(xx, nl, marker='_', s=900, color='k', label='random-timing null, 99th pct'); a.set_xticks(xx); a.set_xticklabels(nm, fontsize=8); a.set_ylabel('out-of-fold F1 (±1 minute)'); a.legend(fontsize=8); a.set_title('C. Only range edge + spacing reproduces the pair times')
for i, v in enumerate(f): a.text(i, v + .01, f'{v:.2f}', ha='center', fontsize=8)
a = ax[1, 1]; M = AL[(AL.family == 'M1') & (AL['info'] == 'bar')].copy(); M['N'] = M.params.str.extract(r'\((\d+),')[0].astype(int); M['K'] = M.params.str.extract(r', (\d+)\)')[0].astype(int)
for N, c in ((60, '#1f77b4'), (90, '#d62728')): d = M[M.N == N].sort_values('K'); a.plot(d.K, d.F1_tol1, 'o-', color=c, label=f'range edge N = {N} min')
a.set_xscale('log'); a.set_xlabel('refractory K (minutes since the tracker\'s last fire; K = 1 is stateless)'); a.set_ylabel('F1 (±1 minute, all cycles, in-sample)'); a.legend(fontsize=8); a.set_title('D. The spacing matters: F1 rises from stateless to K ≈ 3–12')
plt.tight_layout(); plt.savefig(f'{FIG}/bl_trk_logic.png', dpi=130); print('ok')
